                delay = retry_delay(exc.headers.get('Retry-After'))
                if delay is None:
                    try:
                        body = json.load(exc)
                    except (ValueError, OSError):
                        body = {}
                    delay = body.get('retry_after_seconds')
                if delay is None:
                    raise RuntimeError('Rate limit response gave no wait time') from exc
                print(f'Rate limited; waiting {delay:g}s', file=sys.stderr, flush=True)
