    if payload['next'] "'!= expected_next:
        raise RuntimeError(f'"'Unexpected pagination link on page {page}: {payload[\"next\"]}')
    if page == total_pages:
        break
    page += 1
    if page % 5 == 1:
        print(f'Fetched {page - 1}/{total_pages} order pages', file=sys.stderr, flush=True)

qualifying = []
for order in seen.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed_at = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00'))
    if placed_at.tzinfo is None:
        raise RuntimeError(f'Order {order[\"id\"]} has a timestamp without an offset')
    if START <= placed_at.astimezone(timezone.utc) < END:
        qualifying.append(order)

customers = {}
by_region = {region: 0 for region in REGIONS}
