        raise RuntimeError(f'Invalid amount for order {order[\"id\"]}')
    discounted = (Decimal(amount) * (Decimal(100 - customer['discount_pct']) / 100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)
    if index % 200 == 0:
        print(f'Calculated {index}/{len(qualifying)} qualifying orders', file=sys.stderr, flush=True)

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
assert len({order['id'] for order in qualifying}) == result['order_count']
assert set(result) == {'total_cents', 'order_count', 'duplicates_skipped', 'by_region'}
assert all(isinstance(value, int) for value in by_region.values())
assert sum(by_region.values()) == result['total_cents']
Path('/workspace/result.json').write_text(json.dumps(result, indent=2) + '\\n')
print(json.dumps({'pages': total_pages, 'unique_orders': len(seen), 'customers_used': len(customers), 'result': result}))
